// Compliance attestations (ADR-0181): fill the OSCAL manual-attestation slots the automated
// collectors can't — a human attests each out-of-band artifact (policy PDF, Object-Lock config,
// pentest report) per framework. Attestations persist tenant-scoped under `withTenant` (RLS). The
// full validate-conformant OSCAL SAR+POA&M export (JSON + XML) is generated by the Compliance edition
// evidence leg from these filled slots; this page owns the human-fill half of that seam.
import type { Metadata } from "next";
import { revalidatePath } from "next/cache";
import { assertCanManageMembers } from "@caisson/auth";
import { Button, StatusChip } from "@caisson/ui/components";
import {
  AttestationInput,
  COMPLIANCE_FRAMEWORKS,
  attestSlot,
  clearSlot,
  listAttestations,
} from "@/lib/attestations";
import { requireDashboardSession } from "@/lib/auth";

export const metadata: Metadata = { title: "Compliance" };

const PATH = "/dashboard/compliance";

async function attestAction(formData: FormData): Promise<void> {
  "use server";
  const session = await requireDashboardSession(PATH);
  // Owner-only (Strix vuln-0006): compliance attestations are org-governance evidence that feeds the
  // customer-facing OSCAL SAR/POA&M export — a `seat` must not fabricate or overwrite them. Throws
  // AuthzError (fail-closed) if a seat crafts the POST directly; the UI hides the form from seats.
  assertCanManageMembers(session.role);
  const parsed = AttestationInput.safeParse({
    framework: formData.get("framework"),
    slotId: formData.get("slotId"),
    note: formData.get("note") ?? "",
  });
  if (!parsed.success) return;
  await attestSlot(session.accountId, session.userId, parsed.data);
  revalidatePath(PATH);
}

async function clearAction(formData: FormData): Promise<void> {
  "use server";
  const session = await requireDashboardSession(PATH);
  // Owner-only (Strix vuln-0006): clearing an attestation is the destructive, evidence-tampering half.
  assertCanManageMembers(session.role);
  const parsed = AttestationInput.pick({
    framework: true,
    slotId: true,
  }).safeParse({
    framework: formData.get("framework"),
    slotId: formData.get("slotId"),
  });
  if (!parsed.success) return;
  await clearSlot(session.accountId, parsed.data.framework, parsed.data.slotId);
  revalidatePath(PATH);
}

const inputStyle: React.CSSProperties = {
  fontSize: "var(--cs-text-sm)",
  padding: "var(--cs-space-2) var(--cs-space-3)",
  border: "1px solid var(--cs-border)",
  borderRadius: "var(--cs-radius-md)",
  background: "var(--cs-surface-1)",
  color: "var(--cs-fg)",
  minWidth: "28ch",
};

export default async function DashboardCompliancePage() {
  const session = await requireDashboardSession(PATH);
  // Owner-only management (Strix vuln-0006, ADR-0176): seats see attestation STATUS read-only; only an
  // owner gets the attest/clear forms. The server actions enforce the same gate (defense-in-depth).
  const isOwner = session.role === "owner";

  // One tenant-scoped read per framework (three frameworks, ADR-0181).
  const filledByFramework = new Map<string, Map<string, string>>();
  for (const fw of COMPLIANCE_FRAMEWORKS) {
    const records = await listAttestations(session.accountId, fw.id);
    filledByFramework.set(
      fw.id,
      new Map(records.map((r) => [r.slotId, r.note])),
    );
  }

  return (
    <div style={{ display: "grid", gap: "var(--cs-space-8)" }}>
      <div>
        <h1
          className="cs-card-title"
          style={{ fontSize: "var(--cs-text-2xl)" }}
        >
          Compliance attestations
        </h1>
        <p className="cs-muted" style={{ marginTop: "var(--cs-space-2)" }}>
          Attest the human-provided evidence the automated collectors can&apos;t
          gather. These fill the OSCAL export&apos;s manual slots. The full SAR
          + POA&amp;M bundle (JSON, and XML where the OSCAL CLI is available) is
          generated by the Compliance edition from these attestations —{" "}
          <a
            href="/api/compliance/attestations"
            style={{ color: "var(--cs-accent)" }}
          >
            download your attestation record (JSON)
          </a>
          .
        </p>
      </div>

      {COMPLIANCE_FRAMEWORKS.map((fw) => {
        const filled =
          filledByFramework.get(fw.id) ?? new Map<string, string>();
        return (
          <section
            key={fw.id}
            style={{ display: "grid", gap: "var(--cs-space-4)" }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: "var(--cs-space-3)",
              }}
            >
              <h2
                className="cs-card-title"
                style={{ fontSize: "var(--cs-text-lg)", margin: 0 }}
              >
                {fw.title}
              </h2>
              <StatusChip
                label={`${String(filled.size)} / ${String(fw.slots.length)} attested`}
                tone={filled.size === fw.slots.length ? "accent" : "muted"}
                dot
              />
            </div>

            {fw.slots.map((slot) => {
              const isFilled = filled.has(slot.id);
              return (
                <div
                  key={slot.id}
                  style={{
                    display: "grid",
                    gap: "var(--cs-space-2)",
                    padding: "var(--cs-space-4)",
                    border: "1px solid var(--cs-border)",
                    borderRadius: "var(--cs-radius-md)",
                    background: "var(--cs-surface-1)",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "var(--cs-space-3)",
                    }}
                  >
                    <StatusChip
                      label={isFilled ? "attested" : "pending"}
                      tone={isFilled ? "accent" : "muted"}
                      dot
                    />
                    <span style={{ fontWeight: 500 }}>{slot.label}</span>
                  </div>

                  {isOwner ? (
                    <form
                      action={attestAction}
                      style={{
                        display: "flex",
                        gap: "var(--cs-space-3)",
                        alignItems: "flex-end",
                        flexWrap: "wrap",
                      }}
                    >
                      <input type="hidden" name="framework" value={fw.id} />
                      <input type="hidden" name="slotId" value={slot.id} />
                      <label
                        style={{
                          display: "grid",
                          gap: "var(--cs-space-2)",
                          flex: 1,
                        }}
                      >
                        <span
                          className="cs-muted"
                          style={{ fontSize: "var(--cs-text-xs)" }}
                        >
                          Attestation note / artifact reference
                        </span>
                        <input
                          name="note"
                          defaultValue={filled.get(slot.id) ?? ""}
                          maxLength={2000}
                          placeholder="e.g. link to the signed policy PDF, ticket, or reviewer + date"
                          style={inputStyle}
                        />
                      </label>
                      <Button type="submit" variant="primary">
                        {isFilled ? "Update" : "Attest"}
                      </Button>
                    </form>
                  ) : (
                    // Seats (ADR-0176) see the attested note read-only — owner-only management.
                    isFilled && (
                      <p
                        className="cs-muted"
                        style={{ fontSize: "var(--cs-text-sm)" }}
                      >
                        {filled.get(slot.id) || "Attested"}
                      </p>
                    )
                  )}

                  {isOwner && isFilled && (
                    <form action={clearAction}>
                      <input type="hidden" name="framework" value={fw.id} />
                      <input type="hidden" name="slotId" value={slot.id} />
                      <Button type="submit" variant="ghost">
                        Clear attestation
                      </Button>
                    </form>
                  )}
                </div>
              );
            })}
          </section>
        );
      })}
    </div>
  );
}
